from typing import List

class Solution:
    def numberOfSets(self, n: int, maxDistance: int, roads: List[List[int]]) -> int:
        # Since n is very small (up to 10), we can iterate through all 2^n subsets
        # of branches that we might decide to keep.

        # A subset of branches is kept if the bit at position i is 1.
        # We represent this as a mask.
        ans = 0

        for mask in range(1 << n):
            # Identify which branches are kept
            active_branches = [i for i in range(n) if (mask & (1 << i))]

            # Distance matrix for the Floyd-Warshall algorithm initialized to infinity
            # We only care about distances between branches currently in "active_branches"
            dist = [[float('inf')] * n for _ in range(n)]
            for i in active_branches:
                dist[i][i] = 0

            # Populate initial edge weights only using roads between active branches
            for u, v, w in roads:
                if (mask & (1 << u)) and (mask & (1 << v)):
                    dist[u][v] = min(dist[u][v], w)
                    dist[v][u] = min(dist[v][u], w)

            # Floyd-Warshall to find all-pairs shortest paths within the chosen induced subgraph
            for k in active_branches:
                for i in active_branches:
                    for j in active_branches:
                        if dist[i][k] + dist[k][j] < dist[i][j]:
                            dist[i][j] = dist[i][k] + dist[k][j]

            # Verify if all active branches satisfy the maxDistance constraint
            valid = True
            for i in active_branches:
                for j in active_branches:
                    if dist[i][j] > maxDistance:
                        valid = False
                        break
                if not valid:
                    break

            if valid:
                ans += 1

        return ans
